  /// failed load keeps the last good snapshot.
  Future<void> refresh() async {
    try {
      _snapshot = await _service.load();
      notifyListeners();
    } on Object {
      // Unsupported platform / unreadable config — stay with the last
      // snapshot (or none).
    }
  }
}
