      // the sandbox root must contain nothing but the sessions directory.
      expect(hostRoot.listSync().map((e) => e.path), [
        '${hostRoot.path}/sessions',
      ]);
      expect(
        Directory('${hostRoot.path}${hostRoot.path}').existsSync(),
        isFalse,
      );
    });

