        final (mountEnv, stored) = await _mountWithStoredMount();
        app_env.applyStoredMount(mountEnv, stored, granted: true);
        expect(mountEnv.mountedRoot, '/proj');
        expect(mountEnv.mountUnavailable, isNull);
